/* === VARIABLES === */
:root {
  --color-primary: #1A2E5A;
  --color-accent: #E63946;
  --color-bg: #F4F6FB;
  --color-surface: #FFFFFF;
  --color-text-main: #1A2E5A;
  --color-text-muted: #6B7280;
  --color-border: #D1D5DB;
  --color-overlay: rgba(0, 0, 0, 0.35);

  --font-family-base: system-ui, -apple-system, 'Segoe UI', Arial, sans-serif;
  --font-size-base: 1rem;
  --font-size-lg: 1.25rem;
  --font-size-xl: 1.75rem;
  --font-size-2xl: 2.5rem;
  --font-size-phrase: clamp(1.4rem, 4vw, 2.8rem);

  --spacing-xs: 0.25rem;
  --spacing-sm: 0.5rem;
  --spacing-md: 1rem;
  --spacing-lg: 1.5rem;
  --spacing-xl: 2rem;
  --spacing-2xl: 3rem;

  --radius-sm: 0.375rem;
  --radius-md: 0.75rem;
  --radius-lg: 1.25rem;

  --shadow-sm: 0 1px 3px rgba(0,0,0,0.10);
  --shadow-md: 0 4px 16px rgba(0,0,0,0.12);
  --shadow-lg: 0 8px 32px rgba(0,0,0,0.18);

  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;

  --dropdown-max-height: 320px;
  --card-min-height: 340px;
}

/* === RESET Y BASE === */
*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: var(--font-family-base);
  font-size: var(--font-size-base);
  background-color: var(--color-bg);
  color: var(--color-text-main);
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

h1,
h2,
h3 {
  margin: 0;
  line-height: 1.2;
}

ul {
  list-style: none;
  margin: 0;
  padding: 0;
}

button {
  cursor: pointer;
  border: none;
  background: none;
  font-family: inherit;
  font-size: inherit;
}

*:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
}

/* === LAYOUT PRINCIPAL === */
.site-header {
  background-color: var(--color-primary);
  color: var(--color-surface);
  padding: var(--spacing-lg) var(--spacing-xl);
  text-align: center;
  box-shadow: var(--shadow-md);
}

.site-title {
  font-size: var(--font-size-xl);
  font-weight: 700;
  letter-spacing: 0.02em;
}

#app {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: var(--spacing-2xl) var(--spacing-md);
  gap: var(--spacing-xl);
}

/* === COMPONENTE DROPDOWN === */
.country-dropdown {
  position: relative;
  width: 100%;
  max-width: 320px;
}

.dropdown-trigger {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--spacing-sm);
  padding: var(--spacing-sm) var(--spacing-md);
  background-color: var(--color-surface);
  border: 2px solid var(--color-border);
  border-radius: var(--radius-md);
  font-size: var(--font-size-lg);
  color: var(--color-text-main);
  box-shadow: var(--shadow-sm);
  transition: border-color var(--transition-fast), box-shadow var(--transition-fast);
}

.dropdown-trigger:hover {
  border-color: var(--color-primary);
  box-shadow: var(--shadow-md);
}

.dropdown-trigger::after {
  content: '▾';
  font-size: var(--font-size-base);
  color: var(--color-text-muted);
  transition: transform var(--transition-base);
  flex-shrink: 0;
}

.country-dropdown.is-open .dropdown-trigger::after {
  transform: rotate(180deg);
}

#dropdown-menu {
  display: none;
  position: absolute;
  top: calc(100% + var(--spacing-xs));
  left: 0;
  right: 0;
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-lg);
  max-height: var(--dropdown-max-height);
  overflow-y: auto;
  z-index: 100;
}

.country-dropdown.is-open #dropdown-menu {
  display: block;
}

.dropdown-option {
  display: flex;
  align-items: center;
  gap: var(--spacing-sm);
  padding: var(--spacing-sm) var(--spacing-md);
  cursor: pointer;
  transition: background-color var(--transition-fast);
  font-size: var(--font-size-base);
}

.dropdown-option:hover {
  background-color: var(--color-bg);
}

.dropdown-option.is-selected {
  background-color: var(--color-primary);
  color: var(--color-surface);
  font-weight: 600;
}

.dropdown-flag {
  font-size: 1.5rem;
  line-height: 1;
  flex-shrink: 0;
}

.dropdown-label {
  flex: 1;
}

/* === ÁREA DE SALUDO === */
#greeting-display {
  width: 100%;
  max-width: 680px;
  position: relative;
  min-height: var(--card-min-height);
}

.greeting-card {
  display: none;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: var(--spacing-lg);
  width: 100%;
  min-height: var(--card-min-height);
  padding: var(--spacing-2xl) var(--spacing-xl);
  background-color: var(--color-surface);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-md);
  text-align: center;
  animation: fadeIn var(--transition-base) ease;
}

.greeting-card.is-active {
  display: flex;
}

@keyframes fadeIn {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.greeting-flag {
  font-size: 5rem;
  line-height: 1;
}

.greeting-phrase {
  font-size: var(--font-size-phrase);
  font-weight: 700;
  color: var(--color-primary);
  line-height: 1.2;
}

.greeting-country {
  font-size: var(--font-size-lg);
  color: var(--color-text-muted);
  font-weight: 400;
}

/* === RESPONSIVIDAD === */
@media (max-width: 480px) {
  .site-header {
    padding: var(--spacing-md) var(--spacing-md);
  }

  .site-title {
    font-size: var(--font-size-lg);
  }

  #app {
    padding: var(--spacing-xl) var(--spacing-sm);
    gap: var(--spacing-lg);
  }

  .country-dropdown {
    max-width: 100%;
